public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly object _lock = new();

    private readonly List<Notification> _notifications =
    [
        new(0, "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-10)),
    ];

    public NotificationService()
    {
        _nextId = _notifications.Count;
    }

    /// <summary>Returns all notifications available right now.</summary>
    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    /// <summary>Returns only notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(int sinceId)
    {
        // Simulate a new notification arriving roughly every 8 seconds
        MaybeAddFakeNotification();

        lock (_lock)
        {
            return Task.FromResult(
                _notifications
                    .Where(n => n.Id > sinceId)
                    .OrderByDescending(n => n.Timestamp)
                    .ToList());
        }
    }

    private static readonly string[] SampleMessages =
    [
        "Your build succeeded.",
        "New comment on your pull request.",
        "Deployment to staging complete.",
        "Disk usage above 80%.",
        "Scheduled maintenance tonight at 11 PM.",
        "New user signed up.",
        "Payment received.",
        "Certificate renewal reminder.",
    ];

    private DateTime _lastGenerated = DateTime.UtcNow;

    private void MaybeAddFakeNotification()
    {
        lock (_lock)
        {
            if ((DateTime.UtcNow - _lastGenerated).TotalSeconds < 8)
                return;

            _lastGenerated = DateTime.UtcNow;
            var msg = SampleMessages[_nextId % SampleMessages.Length];
            _notifications.Add(new Notification(_nextId, msg, DateTime.UtcNow));
            _nextId++;
        }
    }
}

